// 项目实战“复刻面试自习室”第 7 关：题库接口，列表、筛选、搜索、分页和科目统计。
// 学习卡片由 .sites-runtime/cards/pj-query-*.mjs 生成（node .sites-runtime/lessons.mjs apply …），题目直接写在这里。
import type {AiLevel} from '../journey';

export const pjQuery:AiLevel={id:'pj-query',title:'题库接口：分页、搜索和科目统计',summary:'题目列表支持科目筛选、关键词搜索和分页，返回总数；新增科目统计接口；参数不合法返回 400',lessons:[
  {title:'这一关做什么：让题库接口好用起来',body:'现在题库有 24 道题，以后会有几百上千道。一次把所有题都返回给前端，又慢又没必要：用户一屏也就看十来道。这一关把题目列表接口做成真正能用的样子：\n一、分页：GET /api/questions?page=2&size=10 返回第 2 页，每页 10 道；\n二、搜索：?q=索引 只返回题目里包含“索引”的题，可以和科目筛选一起用；\n三、返回格式改成 {"items": [...], "total": 24, "page": 1, "size": 10}，前端才知道一共有多少道、要显示几页；\n四、参数检查：page、size 不是正整数，或者 size 超过 50，返回 400；\n五、新增科目列表接口 GET /api/categories，返回每个科目和它的题目数量，页面上的科目按钮以后就不用写死了。\n返回格式变了，第 5 关写的页面也要跟着改两行，最后有一张任务卡专门讲。'},
  {title:'分页：LIMIT 和 OFFSET',body:'SQL 用 LIMIT 和 OFFSET 实现分页：LIMIT 10 表示最多取 10 行，OFFSET 20 表示先跳过前 20 行。第 page 页、每页 size 条，就是：\nLIMIT size OFFSET (page - 1) × size\n比如每页 10 条：第 1 页跳过 0 条，第 2 页跳过 10 条，第 3 页跳过 20 条，只剩 4 条。\n分页一定要配合 ORDER BY：没有明确的排序时，数据库不保证每次返回的顺序一样，翻页时可能出现“这页的题下一页又出现了”或者“有的题永远看不到”。我们按 id 排序。\n前端还需要知道总共有多少条，才能算出一共几页（总页数 = 总数 ÷ 每页条数，向上取整）。所以要再执行一次 SELECT COUNT(*)，条件和查列表时完全相同，只是不加 LIMIT。\n页码超出范围（比如第 100 页）不算错误，返回空的 items 就行。'},
  {title:'搜索：LIKE 模糊匹配',body:'SQL 的 LIKE 用来做简单的模糊匹配：title LIKE \'%索引%\' 表示 title 里任何位置包含“索引”。% 代表任意多个字符（包括零个），_ 代表恰好一个字符。\n搜索词同样来自用户，也要用占位符传入。写法是把百分号和参数拼在 SQL 里：title LIKE \'%\' || ? || \'%\'，|| 是 SQL 里连接字符串的运算符（MySQL 里要写成 CONCAT(\'%\', ?, \'%\')）。\n为了让“有没有科目”“有没有关键词”的各种组合都能用同一条 SQL，我们用这个技巧：WHERE (? = \'\' OR category = ?) AND (? = \'\' OR title LIKE \'%\' || ? || \'%\')。参数为空时，括号里第一个条件成立，这个筛选就相当于没有。\n两个提醒：一、用户输入的 % 和 _ 也会被当作通配符，对我们的题库影响不大，正式的系统会把它们转义；二、LIKE \'%词%\' 用不上普通索引，数据量很大时要用全文搜索（比如 Elasticsearch），这里先不考虑。'},
  {title:'统计：GROUP BY',body:'科目列表接口要返回“每个科目有几道题”，用 GROUP BY 分组统计：\nSELECT category, COUNT(*) AS count FROM questions GROUP BY category ORDER BY category\nGROUP BY category 把 category 相同的行归成一组，COUNT(*) 数出每组的行数，AS count 给这一列起名。结果是三行：go 11、mysql 8、redis 5。\n以后再加新科目的题目，这个接口自动就会多出一行，页面上的科目按钮也会自动多一个，不用改任何代码。这就是“数据驱动”的好处。'},
  {title:'参数检查：别相信任何输入',body:'page 和 size 来自地址栏，用户可以随便填：page=abc、page=-1、size=100000。如果不检查：abc 可能让程序出错返回 500；负数会让 OFFSET 变成负的；size 特别大时，一个请求就能把整张表拖出来，被人反复请求，服务器就扛不住了。\n规则：\n一、没传就用默认值：page 默认 1，size 默认 10；\n二、传了就必须是正整数，size 最大 50，否则返回 400 和 {"error": "…"}，告诉调用方哪里不对；\n三、关键词去掉首尾空格，空的就当作没传。\n参数检查写在处理请求的层：它是“接口约定”的一部分，数据访问层只管按给定的条件查数据。各个框架都有自动校验参数的功能（比如 FastAPI 的 Query(ge=1)），用了以后要注意把它的报错格式也统一成我们的 {"error": …}。'},
  {title:'新的接口约定',body:'动手之前，先把接口约定写清楚。前端和后端都按这份约定来写，验收脚本也按它检查。',code:`GET /api/questions?category=go&q=索引&page=1&size=10
→ 200 {"items": [题目, ...], "total": 2, "page": 1, "size": 10}
→ 400 {"error": "page 和 size 必须是正整数，size 最大 50"}

GET /api/categories
→ 200 [{"category": "go", "count": 11}, {"category": "mysql", "count": 8}, {"category": "redis", "count": 5}]

GET /api/questions/{id}
→ 不变`,explain:[{at:'GET /api/questions?category=go&q=索引&page=1&size=10',text:'四个参数都可以不传：category 科目，q 搜索关键词，page 页码（默认 1），size 每页条数（默认 10，最大 50）。'},{at:'→ 200 {"items": [题目, ...], "total": 2, "page": 1, "size": 10}',text:'成功时返回一个对象：items 是这一页的题目，total 是符合条件的总数（不是这一页的数量），page 和 size 原样返回，前端算页数时要用。'},{at:'→ 400 {"error": "page 和 size 必须是正整数，size 最大 50"}',text:'参数不合法时返回 400。'},{at:'GET /api/categories',to:'→ 200 [{"category": "go"',text:'科目列表：每个科目和它的题目数量，按科目名排序。'},{at:'GET /api/questions/{id}',to:'→ 不变',text:'详情接口不变。'}]},
  {title:'任务一：分页、搜索和科目统计',body:'按新的约定改写题目列表接口，新增科目列表接口。数据访问层负责查询，处理请求的层负责检查参数。按你选的后端语言显示具体写法。',variants:{go:{body:'Go 的改法：数据访问层新增查询条件 ListFilter 和返回结果 Page，List 改成同时查“这一页的题”和“总数”；新增 Categories 做科目统计。处理请求的层负责检查 page、size，再把条件交给数据访问层。\nGo 的 database/sql 需要把参数一个个传进去。args... 的写法表示“把切片展开成多个参数”；append(args, a, b) 在原来四个参数后面再加上 LIMIT 和 OFFSET 的值。',practice:{steps:['按代码第一部分修改 store.go：加上三个类型和 where 常量，用新的 List 换掉旧的，新增 Categories，补完 TODO。','按第二部分修改 handler.go：加 positiveInt，改写 listQuestions，新增 categories，并在 Routes 里注册 GET /api/categories。','go run . 启动，打开 /api/questions?page=3 和 /api/categories 看看。模板渲染的同学先别急，home 里的 List 调用要等最后一个任务一起改，否则编译不过可以先把那几行注释掉。'],expect:'{"items":[{"id":21,...},...],"total":24,"page":3,"size":10}'},code:'// internal/store/store.go（新增类型，替换原来的 List）\ntype ListFilter struct {\n    Category string\n    Keyword  string\n    Page     int\n    Size     int\n}\n\ntype Page struct {\n    Items []Question `json:"items"`\n    Total int        `json:"total"`\n    Page  int        `json:"page"`\n    Size  int        `json:"size"`\n}\n\ntype CategoryCount struct {\n    Category string `json:"category"`\n    Count    int    `json:"count"`\n}\n\nconst where = " WHERE (? = \'\' OR category = ?) AND (? = \'\' OR title LIKE \'%\' || ? || \'%\')"\n\nfunc (s *QuestionStore) List(f ListFilter) (Page, error) {\n    args := []any{f.Category, f.Category, f.Keyword, f.Keyword}\n    page := Page{Items: []Question{}, Page: f.Page, Size: f.Size}\n    // TODO 1：执行 "SELECT COUNT(*) FROM questions"+where，参数是 args...，结果 Scan 进 page.Total\n    // TODO 2：执行 "SELECT "+columns+" FROM questions"+where+" ORDER BY id LIMIT ? OFFSET ?"，\n    //         参数是 append(args, 每页条数, 跳过的条数)...；逐行 scanQuestion，追加到 page.Items\n    return page, nil\n}\n\nfunc (s *QuestionStore) Categories() ([]CategoryCount, error) {\n    // TODO 3：执行 SELECT category, COUNT(*) FROM questions GROUP BY category ORDER BY category，\n    //         把每一行 Scan 进 CategoryCount，返回列表（没有数据时返回空列表）\n    return []CategoryCount{}, nil\n}\n\n// internal/handler/handler.go（Routes 里加一行 mux.HandleFunc("GET /api/categories", h.categories)，import 里加上 "strings"）\n// positiveInt 读取一个正整数参数；没传时返回默认值，格式不对时 ok 为 false。\nfunc positiveInt(r *http.Request, name string, def int) (n int, ok bool) {\n    s := r.URL.Query().Get(name)\n    if s == "" {\n        return def, true\n    }\n    n, err := strconv.Atoi(s)\n    return n, err == nil && n > 0\n}\n\nfunc (h *Handler) listQuestions(w http.ResponseWriter, r *http.Request) {\n    // TODO 4：用 positiveInt 读出 page（默认 1）和 size（默认 10）；格式不对或 size > 50 时\n    //         返回 400 和 {"error": "page 和 size 必须是正整数，size 最大 50"}\n    // TODO 5：调用 h.store.List，ListFilter 里填上科目、去掉首尾空格的关键词 q（strings.TrimSpace）、页码和条数；\n    //         出错交给 h.serverError，成功时返回结果\n}\n\nfunc (h *Handler) categories(w http.ResponseWriter, r *http.Request) {\n    // TODO 6：调用 h.store.Categories()，出错交给 h.serverError，成功时返回列表\n}',explain:[{at:'// internal/store/store.go',text:'数据访问层新增三个类型和两个方法，原来的 List 整个换掉，Get、ImportIfEmpty 不变。'},{at:'type ListFilter struct {',to:'Size     int',text:'查询条件：科目、关键词、页码、每页条数。参数越来越多时，放进一个结构体比写一长串参数清楚。'},{at:'type Page struct {',to:'Size  int        `json:"size"`',text:'一页的结果，直接作为接口的 JSON 返回：items 是这一页的题，total 是符合条件的总数。'},{at:'type CategoryCount struct {',to:'Count    int    `json:"count"`',text:'科目统计的一行：科目名和题目数量。'},{at:'const where =',text:'列表和计数共用的筛选条件。四个问号依次是：科目、科目、关键词、关键词。参数为空时对应的条件自动失效。'},{at:'func (s *QuestionStore) List(f ListFilter) (Page, error) {',to:'page := Page{Items: []Question{}, Page: f.Page, Size: f.Size}',text:'准备好四个筛选参数，和一个空的结果。Items 先设成空切片，没有数据时返回 [] 而不是 null。要你补全查询。'},{at:'return page, nil',text:'补完后，查询出错的地方要返回错误。'},{at:'func (s *QuestionStore) Categories() ([]CategoryCount, error) {',to:'return []CategoryCount{}, nil',text:'分组统计，要你补全。'},{at:'// internal/handler/handler.go',text:'处理请求的层：新增一个小工具函数和一个接口，改写 listQuestions。'},{at:'func positiveInt(r *http.Request, name string, def int) (n int, ok bool) {',to:'return n, err == nil && n > 0',text:'返回值起了名字 n 和 ok，读起来更清楚。没传参数用默认值；传了就要能转成整数并且大于 0。'},{at:'func (h *Handler) listQuestions(',text:'列表接口，要你补全。'},{at:'func (h *Handler) categories(',text:'科目列表接口，要你补全。'}],solution:{code:'// internal/store/store.go（新增类型，替换原来的 List）\ntype ListFilter struct {\n    Category string\n    Keyword  string\n    Page     int\n    Size     int\n}\n\ntype Page struct {\n    Items []Question `json:"items"`\n    Total int        `json:"total"`\n    Page  int        `json:"page"`\n    Size  int        `json:"size"`\n}\n\ntype CategoryCount struct {\n    Category string `json:"category"`\n    Count    int    `json:"count"`\n}\n\nconst where = " WHERE (? = \'\' OR category = ?) AND (? = \'\' OR title LIKE \'%\' || ? || \'%\')"\n\nfunc (s *QuestionStore) List(f ListFilter) (Page, error) {\n    args := []any{f.Category, f.Category, f.Keyword, f.Keyword}\n    page := Page{Items: []Question{}, Page: f.Page, Size: f.Size}\n    if err := s.db.QueryRow("SELECT COUNT(*) FROM questions"+where, args...).Scan(&page.Total); err != nil {\n        return page, err\n    }\n    rows, err := s.db.Query("SELECT "+columns+" FROM questions"+where+" ORDER BY id LIMIT ? OFFSET ?",\n        append(args, f.Size, (f.Page-1)*f.Size)...)\n    if err != nil {\n        return page, err\n    }\n    defer rows.Close()\n    for rows.Next() {\n        q, err := scanQuestion(rows)\n        if err != nil {\n            return page, err\n        }\n        page.Items = append(page.Items, q)\n    }\n    return page, rows.Err()\n}\n\nfunc (s *QuestionStore) Categories() ([]CategoryCount, error) {\n    rows, err := s.db.Query("SELECT category, COUNT(*) FROM questions GROUP BY category ORDER BY category")\n    if err != nil {\n        return nil, err\n    }\n    defer rows.Close()\n    result := []CategoryCount{}\n    for rows.Next() {\n        var c CategoryCount\n        if err := rows.Scan(&c.Category, &c.Count); err != nil {\n            return nil, err\n        }\n        result = append(result, c)\n    }\n    return result, rows.Err()\n}\n\n// internal/handler/handler.go（Routes 里加一行 mux.HandleFunc("GET /api/categories", h.categories)，import 里加上 "strings"）\n// positiveInt 读取一个正整数参数；没传时返回默认值，格式不对时 ok 为 false。\nfunc positiveInt(r *http.Request, name string, def int) (n int, ok bool) {\n    s := r.URL.Query().Get(name)\n    if s == "" {\n        return def, true\n    }\n    n, err := strconv.Atoi(s)\n    return n, err == nil && n > 0\n}\n\nfunc (h *Handler) listQuestions(w http.ResponseWriter, r *http.Request) {\n    page, ok1 := positiveInt(r, "page", 1)\n    size, ok2 := positiveInt(r, "size", 10)\n    if !ok1 || !ok2 || size > 50 {\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": "page 和 size 必须是正整数，size 最大 50"})\n        return\n    }\n    query := r.URL.Query()\n    result, err := h.store.List(store.ListFilter{\n        Category: query.Get("category"),\n        Keyword:  strings.TrimSpace(query.Get("q")),\n        Page:     page,\n        Size:     size,\n    })\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, result)\n}\n\nfunc (h *Handler) categories(w http.ResponseWriter, r *http.Request) {\n    result, err := h.store.Categories()\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    writeJSON(w, http.StatusOK, result)\n}',explain:[{at:'// internal/store/store.go',text:'数据访问层新增三个类型和两个方法，原来的 List 整个换掉，Get、ImportIfEmpty 不变。'},{at:'type ListFilter struct {',to:'Size     int',text:'查询条件：科目、关键词、页码、每页条数。参数越来越多时，放进一个结构体比写一长串参数清楚。'},{at:'type Page struct {',to:'Size  int        `json:"size"`',text:'一页的结果，直接作为接口的 JSON 返回：items 是这一页的题，total 是符合条件的总数。'},{at:'type CategoryCount struct {',to:'Count    int    `json:"count"`',text:'科目统计的一行：科目名和题目数量。'},{at:'const where =',text:'列表和计数共用的筛选条件。四个问号依次是：科目、科目、关键词、关键词。参数为空时对应的条件自动失效。'},{at:'func (s *QuestionStore) List(f ListFilter) (Page, error) {',to:'page := Page{Items: []Question{}, Page: f.Page, Size: f.Size}',text:'准备筛选参数和空结果。[]any 是“可以放任何类型的切片”。'},{at:'if err := s.db.QueryRow("SELECT COUNT(*) FROM questions"+where, args...).Scan(&page.Total); err != nil {',to:'return page, err',text:'先查总数，条件和列表完全相同，只是不分页。'},{at:'rows, err := s.db.Query("SELECT "+columns',to:'append(args, f.Size, (f.Page-1)*f.Size)...)',text:'再查这一页：按 id 排序，LIMIT 每页条数，OFFSET 跳过前面几页的条数。'},{at:'if err != nil {',to:'defer rows.Close()',text:'出错返回，记得关闭结果集。'},{at:'for rows.Next() {',to:'page.Items = append(page.Items, q)',text:'逐行读出，追加到这一页。'},{at:'return page, rows.Err()',text:'返回这一页。'},{at:'func (s *QuestionStore) Categories() ([]CategoryCount, error) {',to:'rows, err := s.db.Query("SELECT category, COUNT(*) FROM questions GROUP BY category ORDER BY category")',text:'按科目分组计数，按科目名排序。'},{at:'if err != nil {',to:'result := []CategoryCount{}',text:'出错返回；准备空列表。'},{at:'for rows.Next() {',to:'return result, rows.Err()',text:'每一行有两列，依次 Scan 进科目名和数量。'},{at:'// internal/handler/handler.go',text:'处理请求的层：新增一个小工具函数和一个接口，改写 listQuestions。'},{at:'func positiveInt(r *http.Request, name string, def int) (n int, ok bool) {',to:'return n, err == nil && n > 0',text:'返回值起了名字 n 和 ok，读起来更清楚。没传参数用默认值；传了就要能转成整数并且大于 0。'},{at:'func (h *Handler) listQuestions(',to:'size, ok2 := positiveInt(r, "size", 10)',text:'读出页码和每页条数。'},{at:'if !ok1 || !ok2 || size > 50 {',to:'return',text:'任何一个不合法都返回 400，并说清楚规则。'},{at:'query := r.URL.Query()',to:'})',text:'组装查询条件交给数据访问层。TrimSpace 去掉关键词首尾的空格。'},{at:'if err != nil {',to:'writeJSON(w, http.StatusOK, result)',text:'出错返回 500，成功返回这一页的结果。'},{at:'func (h *Handler) categories(',to:'writeJSON(w, http.StatusOK, result)',text:'科目列表接口：直接返回统计结果。'}]}},java:{body:'Java 的改法：新增两个 record 表示“一页结果”和“科目统计”；仓库新增 findPage 和 countByCategory；控制器检查 page、size 的范围；GlobalErrors 把“参数格式不对”（比如 page=abc）统一成 400。\n科目列表的路径是 /api/categories，不在 /api/questions 下面。最简单的做法是把控制器类上的前缀改成 /api，两个题目方法的路径相应地加上 /questions。',practice:{steps:['新建 model/Page.java 和 model/CategoryCount.java（代码第一部分）。','按第二部分修改仓库，补完 TODO。','按第三部分修改控制器：把类上的 @RequestMapping 改成 "/api"，列表方法写 @GetMapping("/questions")，详情方法写 @GetMapping("/questions/{id}")，再加上 categories 方法。','按最后一部分修改 GlobalErrors。','打开 /api/questions?page=3、/api/questions?page=abc 和 /api/categories 看看。'],expect:'{"items":[{"id":21,...},...],"total":24,"page":3,"size":10}'},code:'// model/Page.java\npackage com.example.zixishi.model;\n\nimport java.util.List;\n\npublic record Page<T>(List<T> items, int total, int page, int size) {}\n\n// model/CategoryCount.java\npackage com.example.zixishi.model;\n\npublic record CategoryCount(String category, int count) {}\n\n// repository/QuestionRepository.java（新增常量和两个方法，替换原来的 findAll；记得导入两个新的 record）\nprivate static final String WHERE =\n    " WHERE (? = \'\' OR category = ?) AND (? = \'\' OR title LIKE \'%\' || ? || \'%\')";\n\npublic Page<Question> findPage(String category, String keyword, int page, int size) {\n    Object[] args = {category, category, keyword, keyword};\n    // TODO 1：用 jdbc.queryForObject("SELECT COUNT(*) FROM questions" + WHERE, Integer.class, args) 查出总数\n    // TODO 2：用 jdbc.query 查 "SELECT " + COLUMNS + " FROM questions" + WHERE + " ORDER BY id LIMIT ? OFFSET ?"，\n    //         参数依次是 category, category, keyword, keyword, 每页条数, 跳过的条数\n    // TODO 3：返回 new Page<>(items, total, page, size)\n    return null;\n}\n\npublic List<CategoryCount> countByCategory() {\n    // TODO 4：SELECT category, COUNT(*) AS count FROM questions GROUP BY category ORDER BY category，\n    //         用 lambda (rs, i) -> new CategoryCount(...) 把每一行变成对象\n    return List.of();\n}\n\n// controller/QuestionController.java（替换原来的 list 方法，新增 categories；详情方法不变）\n@GetMapping\npublic ResponseEntity<?> list(@RequestParam(defaultValue = "") String category,\n                              @RequestParam(defaultValue = "") String q,\n                              @RequestParam(defaultValue = "1") int page,\n                              @RequestParam(defaultValue = "10") int size) {\n    // TODO 5：page 或 size 小于 1、或 size 大于 50 时返回 400 和 {"error": "page 和 size 必须是正整数，size 最大 50"}\n    // TODO 6：否则返回 ResponseEntity.ok(repo.findPage(...))，关键词用 q.strip() 去掉首尾空格\n    return null;\n}\n\n// TODO 7：新增 categories 方法，返回 repo.countByCategory()。\n//         注意这个控制器的路径前缀是 /api/questions，科目列表要放在 /api/categories：\n//         可以在方法上写 @GetMapping("/categories")，并把类上的 @RequestMapping 改成 "/api"、\n//         两个题目方法的路径改成 "/questions" 和 "/questions/{id}"\n\n// config/GlobalErrors.java（新增一个方法，放在处理 Exception 的方法前面）\n@ExceptionHandler(MethodArgumentTypeMismatchException.class)\npublic ResponseEntity<Map<String, String>> badParam() {\n    return ResponseEntity.badRequest().body(Map.of("error", "参数格式不对"));\n}',explain:[{at:'// model/Page.java',to:'public record Page<T>(List<T> items, int total, int page, int size) {}',text:'一页的结果。<T> 是泛型：items 里可以放任何类型，这里放 Question。record 会被 Spring 直接转成 {"items": …, "total": …, "page": …, "size": …}。'},{at:'// model/CategoryCount.java',to:'public record CategoryCount(String category, int count) {}',text:'科目统计的一行：科目名和题目数量。'},{at:'// repository/QuestionRepository.java',text:'仓库：findAll 换成 findPage，新增 countByCategory。findById、count、insertAll 不变。'},{at:'private static final String WHERE =',to:'" WHERE (? = \'\' OR category = ?)',text:'列表和计数共用的筛选条件。四个问号依次是科目、科目、关键词、关键词。参数为空字符串时对应条件自动失效。'},{at:'public Page<Question> findPage(',to:'Object[] args = {category, category, keyword, keyword};',text:'把四个筛选参数放进数组，几个查询都要用。要你补全查询。'},{at:'return null;',text:'补完后返回真正的结果。'},{at:'public List<CategoryCount> countByCategory() {',to:'return List.of();',text:'分组统计，要你补全。'},{at:'// controller/QuestionController.java',text:'控制器：列表方法加上新参数并检查范围。'},{at:'@GetMapping',to:'@RequestParam(defaultValue = "10") int size) {',text:'四个参数都有默认值。声明成 int 后，Spring 会自动把字符串转成整数；转换失败（比如 page=abc）会抛出 MethodArgumentTypeMismatchException，最后一部分在 GlobalErrors 里处理它。返回类型 ResponseEntity<?> 让一个方法既能返回数据，也能返回 400。'},{at:'return null;',to:'}',text:'要你补全参数检查和返回结果。'},{at:'// config/GlobalErrors.java',text:'全局错误处理：参数类型转换失败时返回 400，而不是被当成“程序出错”返回 500。需要导入 org.springframework.web.method.annotation.MethodArgumentTypeMismatchException。'},{at:'@ExceptionHandler(MethodArgumentTypeMismatchException.class)',to:'return ResponseEntity.badRequest().body(Map.of("error", "参数格式不对"));',text:'Spring 会选择最匹配的那个处理方法，所以这种异常走这里，其他异常仍然走 500。'}],solution:{code:'// model/Page.java\npackage com.example.zixishi.model;\n\nimport java.util.List;\n\npublic record Page<T>(List<T> items, int total, int page, int size) {}\n\n// model/CategoryCount.java\npackage com.example.zixishi.model;\n\npublic record CategoryCount(String category, int count) {}\n\n// repository/QuestionRepository.java（新增常量和两个方法，替换原来的 findAll；记得导入两个新的 record）\nprivate static final String WHERE =\n    " WHERE (? = \'\' OR category = ?) AND (? = \'\' OR title LIKE \'%\' || ? || \'%\')";\n\npublic Page<Question> findPage(String category, String keyword, int page, int size) {\n    Object[] args = {category, category, keyword, keyword};\n    int total = jdbc.queryForObject("SELECT COUNT(*) FROM questions" + WHERE, Integer.class, args);\n    List<Question> items = jdbc.query("SELECT " + COLUMNS + " FROM questions" + WHERE + " ORDER BY id LIMIT ? OFFSET ?",\n        MAPPER, category, category, keyword, keyword, size, (page - 1) * size);\n    return new Page<>(items, total, page, size);\n}\n\npublic List<CategoryCount> countByCategory() {\n    return jdbc.query("SELECT category, COUNT(*) AS count FROM questions GROUP BY category ORDER BY category",\n        (rs, i) -> new CategoryCount(rs.getString("category"), rs.getInt("count")));\n}\n\n// controller/QuestionController.java（替换原来的 list 方法，新增 categories；详情方法不变）\n@GetMapping("/questions")\npublic ResponseEntity<?> list(@RequestParam(defaultValue = "") String category,\n                              @RequestParam(defaultValue = "") String q,\n                              @RequestParam(defaultValue = "1") int page,\n                              @RequestParam(defaultValue = "10") int size) {\n    if (page < 1 || size < 1 || size > 50) {\n        return ResponseEntity.badRequest().body(Map.of("error", "page 和 size 必须是正整数，size 最大 50"));\n    }\n    return ResponseEntity.ok(repo.findPage(category, q.strip(), page, size));\n}\n\n@GetMapping("/categories")\npublic List<CategoryCount> categories() {\n    return repo.countByCategory();\n}\n\n// config/GlobalErrors.java（新增一个方法，放在处理 Exception 的方法前面）\n@ExceptionHandler(MethodArgumentTypeMismatchException.class)\npublic ResponseEntity<Map<String, String>> badParam() {\n    return ResponseEntity.badRequest().body(Map.of("error", "参数格式不对"));\n}',explain:[{at:'// model/Page.java',to:'public record Page<T>(List<T> items, int total, int page, int size) {}',text:'一页的结果。<T> 是泛型：items 里可以放任何类型，这里放 Question。record 会被 Spring 直接转成 {"items": …, "total": …, "page": …, "size": …}。'},{at:'// model/CategoryCount.java',to:'public record CategoryCount(String category, int count) {}',text:'科目统计的一行：科目名和题目数量。'},{at:'// repository/QuestionRepository.java',text:'仓库：findAll 换成 findPage，新增 countByCategory。findById、count、insertAll 不变。'},{at:'private static final String WHERE =',to:'" WHERE (? = \'\' OR category = ?)',text:'列表和计数共用的筛选条件。四个问号依次是科目、科目、关键词、关键词。参数为空字符串时对应条件自动失效。'},{at:'public Page<Question> findPage(',to:'Object[] args = {category, category, keyword, keyword};',text:'四个筛选参数。'},{at:'int total = jdbc.queryForObject(',text:'先查总数，条件和列表相同，不分页。最后的 args 会依次填进四个问号。'},{at:'List<Question> items = jdbc.query(',to:'MAPPER, category, category, keyword, keyword, size, (page - 1) * size);',text:'再查这一页：按 id 排序，LIMIT 每页条数，OFFSET 跳过前面几页的条数。'},{at:'return new Page<>(items, total, page, size);',text:'返回这一页的结果。'},{at:'public List<CategoryCount> countByCategory() {',to:'(rs, i) -> new CategoryCount(rs.getString("category"), rs.getInt("count")));',text:'按科目分组计数，用一个临时的 lambda 把每一行变成 CategoryCount。'},{at:'// controller/QuestionController.java',text:'控制器：类上的前缀已经改成 /api。'},{at:'@GetMapping("/questions")',to:'@RequestParam(defaultValue = "10") int size) {',text:'列表方法，四个参数都有默认值，Spring 自动把字符串转成整数。'},{at:'if (page < 1 || size < 1 || size > 50) {',to:'return ResponseEntity.badRequest()',text:'范围不对返回 400。'},{at:'return ResponseEntity.ok(repo.findPage(category, q.strip(), page, size));',text:'返回这一页。strip 去掉关键词首尾的空格。'},{at:'@GetMapping("/categories")',to:'return repo.countByCategory();',text:'科目列表接口，路径是 /api/categories。'},{at:'// config/GlobalErrors.java',text:'全局错误处理：参数类型转换失败时返回 400，而不是被当成“程序出错”返回 500。需要导入 org.springframework.web.method.annotation.MethodArgumentTypeMismatchException。'},{at:'@ExceptionHandler(MethodArgumentTypeMismatchException.class)',to:'return ResponseEntity.badRequest().body(Map.of("error", "参数格式不对"));',text:'Spring 会选择最匹配的那个处理方法，所以这种异常走这里，其他异常仍然走 500。'}]}},node:{body:'Node.js 的改法：数据访问层的 listQuestions 改成接收一个“查询条件对象”，返回 { items, total, page, size }；新增 listCategories。路由层检查 page、size 后调用它，app.js 注册科目列表接口。\n函数参数写成 { category = "", keyword = "", page = 1, size = 10 } = {}，这叫“解构参数”：调用时传一个对象，没传的属性用等号后面的默认值；最后的 = {} 让完全不传参数时也不会出错。',practice:{steps:['按代码第一部分修改 src/db/questions.js，补完 TODO，导出时加上 listCategories。','按第二部分修改 src/routes/questions.js 里的列表路由。','按第三部分修改 app.js。','打开 /api/questions?page=3 和 /api/categories 看看。'],expect:'{"items":[{"id":21,...},...],"total":24,"page":3,"size":10}'},code:'// src/db/questions.js（getQuestion 不变）\nconst { db } = require("./database");\n\nconst COLUMNS = "id, category, title, answer, difficulty";\nconst WHERE = "WHERE (@category = \'\' OR category = @category) AND (@keyword = \'\' OR title LIKE \'%\' || @keyword || \'%\')";\n\n// 分页查询：返回 { items, total, page, size }\nfunction listQuestions({ category = "", keyword = "", page = 1, size = 10 } = {}) {\n  const params = { category, keyword };\n  // TODO 1：用 SELECT COUNT(*) AS total FROM questions ${WHERE} 查出总数（.get(params)）\n  // TODO 2：用 SELECT ${COLUMNS} FROM questions ${WHERE} ORDER BY id LIMIT @limit OFFSET @offset 查出这一页，\n  //         参数是 { ...params, limit: 每页条数, offset: 跳过的条数 }\n  // TODO 3：返回 { items, total, page, size }\n}\n\n// 每个科目的题目数量：[{ category, count }]\nfunction listCategories() {\n  // TODO 4：SELECT category, COUNT(*) AS count FROM questions GROUP BY category ORDER BY category\n}\n\nmodule.exports = { listQuestions, listCategories, getQuestion };\n\n// src/routes/questions.js（只列出要改的部分，详情路由不变）\n// 读取正整数参数：没传返回默认值，格式不对返回 null\nfunction positiveInt(value, def) {\n  if (value === undefined || value === "") return def;\n  const n = Number(value);\n  return Number.isInteger(n) && n > 0 ? n : null;\n}\n\nrouter.get("/", (req, res) => {\n  // TODO 5：用 positiveInt 读出 page（默认 1）和 size（默认 10）；不合法或 size > 50 时\n  //         返回 400 和 { error: "page 和 size 必须是正整数，size 最大 50" }\n  // TODO 6：调用 listQuestions，传入科目、去掉首尾空格的关键词 req.query.q、页码和条数，返回结果\n});\n\n// app.js：在 app.use("/api", notFound) 前面加上科目列表接口（顶部导入 listCategories）\nconst { listCategories } = require("./src/db/questions");\n\napp.get("/api/categories", (req, res) => {\n  res.json(listCategories());\n});',explain:[{at:'// src/db/questions.js',to:'const { db } = require("./database");',text:'数据访问层：listQuestions 改成分页查询，新增 listCategories。'},{at:'const COLUMNS',text:'要查询的列。'},{at:'const WHERE',text:'列表和计数共用的筛选条件。用命名占位符 @category、@keyword，同一个名字出现两次也只要传一次值。参数为空字符串时，对应的条件自动失效。'},{at:'function listQuestions({ category = "", keyword = "", page = 1, size = 10 } = {}) {',to:'const params = { category, keyword };',text:'解构参数并准备好筛选参数。要你补全查询。'},{at:'function listCategories() {',text:'分组统计，要你补全。'},{at:'module.exports = { listQuestions, listCategories, getQuestion };',text:'导出时加上 listCategories。'},{at:'// src/routes/questions.js',text:'路由层负责检查参数。'},{at:'function positiveInt(value, def) {',to:'return Number.isInteger(n) && n > 0 ? n : null;',text:'没传就用默认值；Number("abc") 得到 NaN，Number("1.5") 是 1.5，都不是正整数，返回 null 表示不合法。'},{at:'router.get("/", (req, res) => {',text:'列表路由，要你补全。'},{at:'// app.js',to:'const { listCategories } = require("./src/db/questions");',text:'入口导入科目统计函数。'},{at:'app.get("/api/categories", (req, res) => {',to:'res.json(listCategories());',text:'科目列表接口。一定要注册在 notFound 之前，否则请求会先被“接口不存在”接走。'}],solution:{code:'// src/db/questions.js（getQuestion 不变）\nconst { db } = require("./database");\n\nconst COLUMNS = "id, category, title, answer, difficulty";\nconst WHERE = "WHERE (@category = \'\' OR category = @category) AND (@keyword = \'\' OR title LIKE \'%\' || @keyword || \'%\')";\n\nfunction listQuestions({ category = "", keyword = "", page = 1, size = 10 } = {}) {\n  const params = { category, keyword };\n  const { total } = db.prepare(`SELECT COUNT(*) AS total FROM questions ${WHERE}`).get(params);\n  const items = db\n    .prepare(`SELECT ${COLUMNS} FROM questions ${WHERE} ORDER BY id LIMIT @limit OFFSET @offset`)\n    .all({ ...params, limit: size, offset: (page - 1) * size });\n  return { items, total, page, size };\n}\n\nfunction listCategories() {\n  return db.prepare("SELECT category, COUNT(*) AS count FROM questions GROUP BY category ORDER BY category").all();\n}\n\nmodule.exports = { listQuestions, listCategories, getQuestion };\n\n// src/routes/questions.js（只列出要改的部分，详情路由不变）\n// 读取正整数参数：没传返回默认值，格式不对返回 null\nfunction positiveInt(value, def) {\n  if (value === undefined || value === "") return def;\n  const n = Number(value);\n  return Number.isInteger(n) && n > 0 ? n : null;\n}\n\nrouter.get("/", (req, res) => {\n  const page = positiveInt(req.query.page, 1);\n  const size = positiveInt(req.query.size, 10);\n  if (page === null || size === null || size > 50) {\n    return res.status(400).json({ error: "page 和 size 必须是正整数，size 最大 50" });\n  }\n  res.json(listQuestions({\n    category: req.query.category || "",\n    keyword: (req.query.q || "").trim(),\n    page,\n    size,\n  }));\n});\n\n// app.js：在 app.use("/api", notFound) 前面加上科目列表接口（顶部导入 listCategories）\nconst { listCategories } = require("./src/db/questions");\n\napp.get("/api/categories", (req, res) => {\n  res.json(listCategories());\n});',explain:[{at:'// src/db/questions.js',to:'const { db } = require("./database");',text:'数据访问层：listQuestions 改成分页查询，新增 listCategories。'},{at:'const COLUMNS',text:'要查询的列。'},{at:'const WHERE',text:'列表和计数共用的筛选条件。用命名占位符 @category、@keyword，同一个名字出现两次也只要传一次值。参数为空字符串时，对应的条件自动失效。'},{at:'function listQuestions({ category = "", keyword = "", page = 1, size = 10 } = {}) {',to:'const params = { category, keyword };',text:'解构参数，准备筛选参数。'},{at:'const { total } = db.prepare(',text:'先查总数：条件和列表相同，不分页。AS total 给结果列起名，解构出来。'},{at:'const items = db',to:'.all({ ...params, limit: size, offset: (page - 1) * size });',text:'再查这一页。...params 把筛选参数展开进新对象，再加上 limit 和 offset 两个值。'},{at:'return { items, total, page, size };',text:'返回这一页的结果，直接就是接口要的格式。'},{at:'function listCategories() {',to:'return db.prepare("SELECT category, COUNT(*) AS count',text:'按科目分组计数，每一行是 { category, count }。'},{at:'module.exports = { listQuestions, listCategories, getQuestion };',text:'导出时加上 listCategories。'},{at:'// src/routes/questions.js',text:'路由层负责检查参数。'},{at:'function positiveInt(value, def) {',to:'return Number.isInteger(n) && n > 0 ? n : null;',text:'没传就用默认值；Number("abc") 得到 NaN，Number("1.5") 是 1.5，都不是正整数，返回 null 表示不合法。'},{at:'router.get("/", (req, res) => {',to:'const size = positiveInt(req.query.size, 10);',text:'读出页码和每页条数。'},{at:'if (page === null || size === null || size > 50) {',to:'return res.status(400).json(',text:'任何一个不合法都返回 400。'},{at:'res.json(listQuestions({',to:'}));',text:'组装查询条件，trim 去掉关键词首尾的空格，返回结果。'},{at:'// app.js',to:'const { listCategories } = require("./src/db/questions");',text:'入口导入科目统计函数。'},{at:'app.get("/api/categories", (req, res) => {',to:'res.json(listCategories());',text:'科目列表接口。一定要注册在 notFound 之前，否则请求会先被“接口不存在”接走。'}]}},python:{body:'Python 的改法：数据访问层的 list_questions 多了关键词、页码和条数三个参数，返回一个包含 items、total、page、size 的字典；新增 list_categories。路由层用 FastAPI 的 Query 声明参数规则，再在 main.py 里把参数错误统一成 400。\n{**params, "limit": 10} 的意思是：把 params 字典里的键值都展开放进新字典，再加上 limit 这一项。',practice:{steps:['按代码第一部分修改 app/db.py，补完 TODO。','按第二部分修改 app/routers/questions.py 的列表路由。','按第三部分修改 main.py。','打开 /api/questions?page=3、/api/questions?page=0 和 /api/categories 看看。'],expect:'{"items":[{"id":21,...},...],"total":24,"page":3,"size":10}'},code:'# app/db.py（get_question 不变）\nfrom app.database import query_all, query_one\n\nCOLUMNS = "id, category, title, answer, difficulty"\nWHERE = ("WHERE (:category = \'\' OR category = :category) "\n         "AND (:keyword = \'\' OR title LIKE \'%\' || :keyword || \'%\')")\n\n\ndef list_questions(category="", keyword="", page=1, size=10):\n    """分页查询，返回 {"items": [...], "total": 总数, "page": 页码, "size": 每页条数}"""\n    params = {"category": category, "keyword": keyword}\n    # TODO 1：用 query_one 执行 SELECT COUNT(*) AS total FROM questions {WHERE}，取出 total\n    # TODO 2：用 query_all 执行 SELECT {COLUMNS} FROM questions {WHERE} ORDER BY id LIMIT :limit OFFSET :offset，\n    #         参数是 {**params, "limit": 每页条数, "offset": 跳过的条数}\n    # TODO 3：返回包含 items、total、page、size 的字典\n    return {}\n\n\ndef list_categories():\n    """每个科目的题目数量"""\n    # TODO 4：SELECT category, COUNT(*) AS count FROM questions GROUP BY category ORDER BY category\n    return []\n\n# app/routers/questions.py（开头改成 from fastapi import APIRouter, Query，\n# from app.db import get_question, list_questions；详情路由不变）\n@router.get("")\ndef list_all(\n    category: str = "",\n    q: str = "",\n    page: int = Query(1, ge=1),\n    size: int = Query(10, ge=1, le=50),\n):\n    # TODO 5：调用 list_questions，关键词用 q.strip() 去掉首尾空格，返回结果\n    pass\n\n# main.py：开头导入 from fastapi.exceptions import RequestValidationError\n# 和 from app.db import list_categories，在兜底路由 not_found 前面加上：\n@app.exception_handler(RequestValidationError)\nasync def bad_request(request: Request, exc: RequestValidationError):\n    return JSONResponse({"error": "参数不合法：page 和 size 必须是正整数，size 最大 50"}, status_code=400)\n\n\n@app.get("/api/categories")\ndef categories():\n    return list_categories()',explain:[{at:'# app/db.py',to:'from app.database import query_all, query_one',text:'数据访问层：list_questions 改成分页查询，新增 list_categories。'},{at:'COLUMNS =',text:'要查询的列。'},{at:'WHERE = (',to:'"AND (:keyword',text:'列表和计数共用的筛选条件，用 :category、:keyword 命名占位符，参数传一个字典。参数为空字符串时，对应的条件自动失效。括号里两段字符串挨着写会自动拼成一段。'},{at:'def list_questions(category="", keyword="", page=1, size=10):',to:'params = {"category": category, "keyword": keyword}',text:'准备好筛选参数。要你补全查询。'},{at:'return {}',text:'补完后改成真正的结果。'},{at:'def list_categories():',to:'return []',text:'分组统计，要你补全。'},{at:'# app/routers/questions.py',text:'路由层：用 FastAPI 的 Query 声明参数规则，框架会自动检查。'},{at:'@router.get("")',to:'):',text:'参数写成函数参数，FastAPI 从地址里读取并转换类型。Query(1, ge=1) 表示默认值 1、必须大于等于 1；le=50 表示小于等于 50。不是整数或者超出范围时，FastAPI 会自动拒绝这个请求。'},{at:'pass',text:'要你补全。'},{at:'# main.py',text:'入口：统一参数错误的格式，注册科目列表接口。'},{at:'@app.exception_handler(RequestValidationError)',to:'return JSONResponse({"error": "参数不合法',text:'FastAPI 参数检查不通过时，默认返回 422 和一大段英文说明，和我们约定的 400 + {"error": …} 不一样。exception_handler 注册一个“出现这种异常时怎么响应”的函数，把格式统一过来。'},{at:'@app.get("/api/categories")',to:'return list_categories()',text:'科目列表接口。要写在兜底路由 /api/{rest:path} 前面，否则会被它先接走。'}],solution:{code:'# app/db.py（get_question 不变）\nfrom app.database import query_all, query_one\n\nCOLUMNS = "id, category, title, answer, difficulty"\nWHERE = ("WHERE (:category = \'\' OR category = :category) "\n         "AND (:keyword = \'\' OR title LIKE \'%\' || :keyword || \'%\')")\n\n\ndef list_questions(category="", keyword="", page=1, size=10):\n    """分页查询，返回 {"items": [...], "total": 总数, "page": 页码, "size": 每页条数}"""\n    params = {"category": category, "keyword": keyword}\n    total = query_one(f"SELECT COUNT(*) AS total FROM questions {WHERE}", params)["total"]\n    items = query_all(\n        f"SELECT {COLUMNS} FROM questions {WHERE} ORDER BY id LIMIT :limit OFFSET :offset",\n        {**params, "limit": size, "offset": (page - 1) * size},\n    )\n    return {"items": items, "total": total, "page": page, "size": size}\n\n\ndef list_categories():\n    """每个科目的题目数量"""\n    return query_all("SELECT category, COUNT(*) AS count FROM questions GROUP BY category ORDER BY category")\n\n# app/routers/questions.py（开头改成 from fastapi import APIRouter, Query，\n# from app.db import get_question, list_questions；详情路由不变）\n@router.get("")\ndef list_all(\n    category: str = "",\n    q: str = "",\n    page: int = Query(1, ge=1),\n    size: int = Query(10, ge=1, le=50),\n):\n    return list_questions(category, q.strip(), page, size)\n\n# main.py：开头导入 from fastapi.exceptions import RequestValidationError\n# 和 from app.db import list_categories，在兜底路由 not_found 前面加上：\n@app.exception_handler(RequestValidationError)\nasync def bad_request(request: Request, exc: RequestValidationError):\n    return JSONResponse({"error": "参数不合法：page 和 size 必须是正整数，size 最大 50"}, status_code=400)\n\n\n@app.get("/api/categories")\ndef categories():\n    return list_categories()',explain:[{at:'# app/db.py',to:'from app.database import query_all, query_one',text:'数据访问层：list_questions 改成分页查询，新增 list_categories。'},{at:'COLUMNS =',text:'要查询的列。'},{at:'WHERE = (',to:'"AND (:keyword',text:'列表和计数共用的筛选条件，用 :category、:keyword 命名占位符，参数传一个字典。参数为空字符串时，对应的条件自动失效。括号里两段字符串挨着写会自动拼成一段。'},{at:'def list_questions(category="", keyword="", page=1, size=10):',to:'params = {"category": category, "keyword": keyword}',text:'准备好筛选参数。'},{at:'total = query_one(',text:'先查总数：条件和列表相同，不分页。AS total 给结果列起名，从返回的字典里取出来。'},{at:'items = query_all(',to:'{**params, "limit": size, "offset": (page - 1) * size},',text:'再查这一页：按 id 排序，LIMIT 每页条数，OFFSET 跳过前面几页的条数。'},{at:'return {"items": items, "total": total, "page": page, "size": size}',text:'返回这一页的结果，直接就是接口要的格式。'},{at:'def list_categories():',to:'return query_all("SELECT category, COUNT(*) AS count',text:'按科目分组计数，每一行是 {"category": …, "count": …}。'},{at:'# app/routers/questions.py',text:'路由层：用 FastAPI 的 Query 声明参数规则，框架会自动检查。'},{at:'@router.get("")',to:'):',text:'参数写成函数参数，FastAPI 从地址里读取并转换类型。Query(1, ge=1) 表示默认值 1、必须大于等于 1；le=50 表示小于等于 50。不是整数或者超出范围时，FastAPI 会自动拒绝这个请求。'},{at:'return list_questions(category, q.strip(), page, size)',text:'参数已经检查过了，直接交给数据访问层。strip 去掉关键词首尾的空格。'},{at:'# main.py',text:'入口：统一参数错误的格式，注册科目列表接口。'},{at:'@app.exception_handler(RequestValidationError)',to:'return JSONResponse({"error": "参数不合法',text:'FastAPI 参数检查不通过时，默认返回 422 和一大段英文说明，和我们约定的 400 + {"error": …} 不一样。exception_handler 注册一个“出现这种异常时怎么响应”的函数，把格式统一过来。'},{at:'@app.get("/api/categories")',to:'return list_categories()',text:'科目列表接口。要写在兜底路由 /api/{rest:path} 前面，否则会被它先接走。'}]}}}},
  {title:'任务二：页面跟上新的返回格式',body:'接口的返回格式从“数组”变成了“对象”，第 5 关写的页面要跟着改，否则页面会显示不出题目。这也提醒我们：接口格式一旦有人在用，改起来就要通知所有调用方，所以接口最好一开始就设计好（真实项目里常用“版本号”来过渡，比如 /api/v2/questions）。按你选的前端做法显示改法。',variants:{html:{body:'接口现在返回的是 {"items": [...], "total": 24, …}，而不是直接返回数组，app.js 里取题目的那一行要改；另外默认每页只有 10 道，翻页功能下一关再做，这一关先在地址里带上 size=50，把题目都取回来。',practice:{steps:['按下面的代码修改 app.js 里 load 函数的前半部分，补完 TODO。','刷新页面，各个科目的题目都能正常显示。'],expect:'共 24 道题（点“全部”时）'},code:'// app.js（load 函数的前半部分）\nasync function load(category) {\n  const params = new URLSearchParams({ size: 50 });\n  if (category) params.set("category", category);\n  const res = await fetch(`/api/questions?${params}`);\n  if (!res.ok) {\n    count.textContent = "加载失败，请稍后再试";\n    return;\n  }\n  // TODO：用 await res.json() 拿到结果对象 data，令 questions = data.items，数量显示 data.total\n',explain:[{at:'async function load(category) {',to:'if (category) params.set("category", category);',text:'URLSearchParams 是浏览器自带的“查询参数”工具：放进去的值会自动编码，转成字符串就是 size=50&category=go 这样的格式，比自己拼字符串省心。'},{at:'const res = await fetch(`/api/questions?${params}`);',to:'return;',text:'发请求，失败时提示，和以前一样。'}],solution:{code:'// app.js（load 函数的前半部分）\nasync function load(category) {\n  const params = new URLSearchParams({ size: 50 });\n  if (category) params.set("category", category);\n  const res = await fetch(`/api/questions?${params}`);\n  if (!res.ok) {\n    count.textContent = "加载失败，请稍后再试";\n    return;\n  }\n  const data = await res.json();\n  const questions = data.items;\n  count.textContent = `共 ${data.total} 道题`;\n',explain:[{at:'async function load(category) {',to:'if (category) params.set("category", category);',text:'用 URLSearchParams 组装查询参数，值会自动编码。'},{at:'const res = await fetch(`/api/questions?${params}`);',to:'return;',text:'发请求，失败时提示。'},{at:'const data = await res.json();',to:'count.textContent = `共 ${data.total} 道题`;',text:'题目在 data.items 里，总数用 data.total。后面创建列表的代码不用改。'}]}},react:{body:'接口现在返回的是 {"items": [...], "total": 24, …}，而不是直接返回数组，App.jsx 里保存题目的地方要改；另外默认每页只有 10 道，翻页功能下一关再做，这一关先在地址里带上 size=50。',practice:{steps:['按下面的代码修改 App.jsx 里的 useEffect，补完 TODO。','npm run dev 打开页面，各个科目的题目都能正常显示。改完记得重新 npm run build。'],expect:'共 24 道题（点“全部”时）'},code:'// App.jsx（useEffect 部分）\nuseEffect(() => {\n  const params = new URLSearchParams({ size: 50 });\n  if (category) params.set("category", category);\n  fetch(`/api/questions?${params}`)\n    .then((res) => {\n      if (!res.ok) throw new Error("加载失败");\n      return res.json();\n    })\n    .then((data) => {\n      // TODO：题目在 data.items 里，用它调用 setQuestions；再 setError("")\n    })\n    .catch(() => setError("加载失败，请稍后再试"));\n}, [category]);',explain:[{at:'useEffect(() => {',to:'if (category) params.set("category", category);',text:'URLSearchParams 是浏览器自带的查询参数工具，值会自动编码，转成字符串就是 size=50&category=go。'},{at:'fetch(`/api/questions?${params}`)',to:'return res.json();',text:'发请求，和以前一样。'},{at:'.then((data) => {',text:'data 现在是一个对象，要你改。'},{at:'.catch(() => setError("加载失败，请稍后再试"));',to:'}, [category]);',text:'出错提示和依赖数组不变。'}],solution:{code:'// App.jsx（useEffect 部分）\nuseEffect(() => {\n  const params = new URLSearchParams({ size: 50 });\n  if (category) params.set("category", category);\n  fetch(`/api/questions?${params}`)\n    .then((res) => {\n      if (!res.ok) throw new Error("加载失败");\n      return res.json();\n    })\n    .then((data) => {\n      setQuestions(data.items);\n      setError("");\n    })\n    .catch(() => setError("加载失败，请稍后再试"));\n}, [category]);',explain:[{at:'useEffect(() => {',to:'if (category) params.set("category", category);',text:'用 URLSearchParams 组装查询参数。'},{at:'fetch(`/api/questions?${params}`)',to:'return res.json();',text:'发请求。'},{at:'.then((data) => {',to:'setError("");',text:'题目在 data.items 里。页面上的“共 N 道题”用的是 questions.length，这里取了全部，数量正好一致。'},{at:'.catch(() => setError("加载失败，请稍后再试"));',to:'}, [category]);',text:'出错提示和依赖数组不变。'}]}},'template-go':{body:'数据访问层的列表函数改成了分页查询，首页调用它的地方要跟着改。翻页功能下一关再做，这一关先一次取 50 道（最多也就 50 道）。科目列表也改成调用 Categories，不用再写死。',practice:{steps:['按下面的代码修改 internal/handler/handler.go 里的 home，补完 TODO。','刷新首页，各个科目的题目都能正常显示。'],expect:'共 24 道题（点“全部”时）'},code:'// internal/handler/handler.go（home 函数）\nfunc (h *Handler) home(w http.ResponseWriter, r *http.Request) {\n    category := r.URL.Query().Get("category")\n    // TODO 1：调用 h.store.List(store.ListFilter{Category: category, Page: 1, Size: 50})，出错交给 h.serverError\n    // TODO 2：调用 h.store.Categories() 拿到科目统计，出错交给 h.serverError\n    // TODO 3：数据里放进 "Category"、"Categories"（科目统计列表）、"Questions"（结果的 Items）和 "Total"，渲染模板\n}\n\n// web/templates/index.html 里改两处：\n// 科目链接：{{range .Categories}}<a href="/?category={{.Category}}">{{.Category}}（{{.Count}}）</a> {{end}}\n// 数量：<p>共 {{.Total}} 道题</p>',explain:[{at:'func (h *Handler) home(',to:'category := r.URL.Query().Get("category")',text:'读出科目参数。'},{at:'TODO',text:'按注释补全，模板文件里的两处修改见最后的注释。'}],solution:{code:'// internal/handler/handler.go（home 函数）\nfunc (h *Handler) home(w http.ResponseWriter, r *http.Request) {\n    category := r.URL.Query().Get("category")\n    result, err := h.store.List(store.ListFilter{Category: category, Page: 1, Size: 50})\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    categories, err := h.store.Categories()\n    if err != nil {\n        h.serverError(w, err)\n        return\n    }\n    data := map[string]any{\n        "Category":   category,\n        "Categories": categories,\n        "Questions":  result.Items,\n        "Total":      result.Total,\n    }\n    w.Header().Set("Content-Type", "text/html; charset=utf-8")\n    if err := h.tmpl.ExecuteTemplate(w, "index.html", data); err != nil {\n        log.Printf("渲染页面出错：%v", err)\n    }\n}\n\n// web/templates/index.html 里改两处：\n// 科目链接：{{range .Categories}}<a href="/?category={{.Category}}">{{.Category}}（{{.Count}}）</a> {{end}}\n// 数量：<p>共 {{.Total}} 道题</p>',explain:[{at:'func (h *Handler) home(',to:'category := r.URL.Query().Get("category")',text:'读出科目参数。'},{at:'result, err := h.store.List(',to:'return',text:'按新的写法查第一页，最多 50 道。'},{at:'categories, err := h.store.Categories()',to:'return',text:'科目也从数据库统计出来。'},{at:'data := map[string]any{',to:'"Total":      result.Total,',text:'Categories 现在是 CategoryCount 列表，模板里要用 .Category 和 .Count 取值。'},{at:'w.Header().Set(',to:'log.Printf("渲染页面出错：%v", err)',text:'渲染模板，和以前一样。'}]}},'template-node':{body:'数据访问层的列表函数改成了分页查询，首页调用它的地方要跟着改。翻页功能下一关再做，这一关先一次取 50 道（最多也就 50 道）。科目列表也改成调用 listCategories，不用再写死。',practice:{steps:['按下面的代码修改 app.js 里的首页路由，补完 TODO。','刷新首页，各个科目的题目都能正常显示。'],expect:'共 24 道题（点“全部”时）'},code:'// app.js（首页路由，顶部导入 listQuestions 和 listCategories）\napp.get("/", (req, res) => {\n  const category = req.query.category || "";\n  // TODO：用 listQuestions({ category, page: 1, size: 50 }) 拿到结果；\n  //       渲染时传入 category、categories: listCategories()、questions: 结果.items、total: 结果.total\n});\n\n// views/index.ejs 里改两处：\n// 科目链接：for (const c of categories) 输出 <a href="/?category=<%= c.category %>"><%= c.category %>（<%= c.count %>）</a>\n// 数量：<p>共 <%= total %> 道题</p>',explain:[{at:'app.get("/", (req, res) => {',to:'const category = req.query.category || "";',text:'读出科目参数。'},{at:'TODO',text:'按注释补全，模板文件里的两处修改见最后的注释。'}],solution:{code:'// app.js（首页路由，顶部导入 listQuestions 和 listCategories）\napp.get("/", (req, res) => {\n  const category = req.query.category || "";\n  const result = listQuestions({ category, page: 1, size: 50 });\n  res.render("index", {\n    category,\n    categories: listCategories(),\n    questions: result.items,\n    total: result.total,\n  });\n});\n\n// views/index.ejs 里改两处：\n// 科目链接：for (const c of categories) 输出 <a href="/?category=<%= c.category %>"><%= c.category %>（<%= c.count %>）</a>\n// 数量：<p>共 <%= total %> 道题</p>',explain:[{at:'app.get("/", (req, res) => {',to:'const category = req.query.category || "";',text:'读出科目参数。'},{at:'const result = listQuestions({ category, page: 1, size: 50 });',text:'按新的写法查第一页，最多 50 道。'},{at:'res.render("index", {',to:'});',text:'科目从数据库统计出来，每一项是 { category, count }；数量用 total。'}]}},'template-python':{body:'数据访问层的列表函数改成了分页查询，首页调用它的地方要跟着改。翻页功能下一关再做，这一关先一次取 50 道（最多也就 50 道）。科目列表也改成调用 list_categories，不用再写死。',practice:{steps:['按下面的代码修改 main.py 里的 home，补完 TODO。','刷新首页，各个科目的题目都能正常显示。'],expect:'共 24 道题（点“全部”时）'},code:'# main.py（home 函数，导入 list_questions 和 list_categories）\n@app.get("/", response_class=HTMLResponse)\ndef home(request: Request, category: str = ""):\n    # TODO：用 list_questions(category, "", 1, 50) 拿到结果；渲染时传入 category、\n    #       categories：list_categories()、questions：结果["items"]、total：结果["total"]\n    pass\n\n# templates/index.html 里改两处：\n# 科目链接：{% for c in categories %}<a href="/?category={{ c.category }}">{{ c.category }}（{{ c.count }}）</a>{% endfor %}\n# 数量：<p>共 {{ total }} 道题</p>',explain:[{at:'@app.get("/", response_class=HTMLResponse)',to:'def home(request: Request, category: str = ""):',text:'首页。'},{at:'TODO',to:'pass',text:'按注释补全，模板文件里的两处修改见最后的注释。'}],solution:{code:'# main.py（home 函数，导入 list_questions 和 list_categories）\n@app.get("/", response_class=HTMLResponse)\ndef home(request: Request, category: str = ""):\n    result = list_questions(category, "", 1, 50)\n    return templates.TemplateResponse(request, "index.html", {\n        "category": category,\n        "categories": list_categories(),\n        "questions": result["items"],\n        "total": result["total"],\n    })\n\n# templates/index.html 里改两处：\n# 科目链接：{% for c in categories %}<a href="/?category={{ c.category }}">{{ c.category }}（{{ c.count }}）</a>{% endfor %}\n# 数量：<p>共 {{ total }} 道题</p>',explain:[{at:'@app.get("/", response_class=HTMLResponse)',to:'def home(request: Request, category: str = ""):',text:'首页。'},{at:'result = list_questions(category, "", 1, 50)',text:'按新的写法查第一页，最多 50 道。'},{at:'return templates.TemplateResponse(',to:'})',text:'科目从数据库统计出来，每一项是 {"category", "count"} 字典；数量用 total。'}]}},'template-java':{body:'数据访问层的列表函数改成了分页查询，首页调用它的地方要跟着改。翻页功能下一关再做，这一关先一次取 50 道（最多也就 50 道）。科目列表也改成调用 countByCategory，不用再写死。',practice:{steps:['按下面的代码修改 PageController，补完 TODO。','刷新首页，各个科目的题目都能正常显示。'],expect:'共 24 道题（点“全部”时）'},code:'// controller/PageController.java（home 方法）\n@GetMapping("/")\npublic String home(@RequestParam(defaultValue = "") String category, Model model) {\n    // TODO：用 repo.findPage(category, "", 1, 50) 拿到结果；model 里放进 category、\n    //       categories（repo.countByCategory()）、questions（结果.items()）、total（结果.total()）\n    return "index";\n}\n\n<!-- templates/index.html 里改两处 -->\n<!-- 科目链接：<a th:each="c : ${categories}" th:href="@{/(category=${c.category()})}" th:text="|${c.category()}（${c.count()}）|">科目</a> -->\n<!-- 数量：<p th:text="|共 ${total} 道题|">共 0 道题</p> -->',explain:[{at:'@GetMapping("/")',to:'public String home(',text:'首页方法。'},{at:'TODO',to:'return "index";',text:'按注释补全，模板文件里的两处修改见最后的注释。'}],solution:{code:'// controller/PageController.java（home 方法）\n@GetMapping("/")\npublic String home(@RequestParam(defaultValue = "") String category, Model model) {\n    Page<Question> result = repo.findPage(category, "", 1, 50);\n    model.addAttribute("category", category);\n    model.addAttribute("categories", repo.countByCategory());\n    model.addAttribute("questions", result.items());\n    model.addAttribute("total", result.total());\n    return "index";\n}\n\n<!-- templates/index.html 里改两处 -->\n<!-- 科目链接：<a th:each="c : ${categories}" th:href="@{/(category=${c.category()})}" th:text="|${c.category()}（${c.count()}）|">科目</a> -->\n<!-- 数量：<p th:text="|共 ${total} 道题|">共 0 道题</p> -->',explain:[{at:'@GetMapping("/")',to:'public String home(',text:'首页方法。'},{at:'Page<Question> result = repo.findPage(category, "", 1, 50);',text:'按新的写法查第一页，最多 50 道。需要导入 Page 和 Question 两个类。'},{at:'model.addAttribute("category", category);',to:'return "index";',text:'科目从数据库统计出来，每一项是 CategoryCount；数量用 total。'}]}}}},
  {title:'验收：分页、搜索和科目统计',body:'这一关的验收脚本检查新的返回格式和每一种查询组合，其中最重要的一项是“翻页不重复、不遗漏”：用每页 7 条把所有页取一遍，拼起来必须正好是 1 到 24 号题，各出现一次。排序没写、OFFSET 算错，都会在这一项暴露出来。\n页面也要自己打开看一眼：题目还能正常显示，科目按钮都能用。',practice:{steps:['保持服务在运行。','把下面的脚本保存为 checks/check_l7.py，运行 python checks/check_l7.py，直到全部 ✓。','全部通过后提交：git add . 然后 git commit -m "第 7 关：分页、搜索和科目统计"。'],expect:'✓ 健康检查仍然正常\n✓ 默认返回第 1 页，每页 10 道，共 24 道\n✓ 第 3 页只剩 4 道（21–24 号）\n✓ 翻页不重复、不遗漏\n✓ 科目和分页可以一起用\n✓ 按关键词搜索\n✓ 搜索词里的 SQL 注入不起作用\n✓ 不合法的 page 和 size 返回 400\n✓ 科目列表和题目数量正确\n✓ 题目详情仍然正常\n\n通过 10 / 10'},code:`import json
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8080"
passed = 0


def check(name, ok):
    global passed
    print(("✓ " if ok else "✗ ") + name)
    passed += bool(ok)


def get(path, **params):
    if params:
        path += "?" + urllib.parse.urlencode(params)
    try:
        with urllib.request.urlopen(BASE + path, timeout=5) as r:
            status, body = r.status, r.read()
    except urllib.error.HTTPError as e:
        status, body = e.code, e.read()
    except OSError as e:
        sys.exit(f"连不上 {BASE}，服务启动了吗？（{e}）")
    try:
        return status, json.loads(body.decode("utf-8") or "null")
    except ValueError:
        return status, None


def ids(data):
    return [q["id"] for q in data["items"]] if isinstance(data, dict) and "items" in data else None


status, data = get("/api/health")
check("健康检查仍然正常", status == 200 and data == {"status": "ok"})

status, data = get("/api/questions")
check("默认返回第 1 页，每页 10 道，共 24 道", status == 200 and isinstance(data, dict)
      and len(data.get("items", [])) == 10 and data.get("total") == 24
      and data.get("page") == 1 and data.get("size") == 10)

_, data = get("/api/questions", page=3)
check("第 3 页只剩 4 道（21–24 号）", ids(data) == [21, 22, 23, 24])

seen = []
for page in range(1, 5):
    seen += ids(get("/api/questions", page=page, size=7)[1]) or []
check("翻页不重复、不遗漏", seen == list(range(1, 25)))

_, data = get("/api/questions", category="go", page=3, size=5)
check("科目和分页可以一起用", isinstance(data, dict) and data.get("total") == 11 and ids(data) == [12])

_, data = get("/api/questions", q="索引")
check("按关键词搜索", isinstance(data, dict) and data.get("total") == 2 and ids(data) == [2, 15])
_, data = get("/api/questions", q="' OR '1'='1")
check("搜索词里的 SQL 注入不起作用", isinstance(data, dict) and data.get("total") == 0)

bad = [get("/api/questions", **p)[0] for p in ({"page": 0}, {"page": "abc"}, {"size": 100}, {"size": -5})]
check("不合法的 page 和 size 返回 400", bad == [400, 400, 400, 400])

status, data = get("/api/categories")
expected = [{"category": "go", "count": 11}, {"category": "mysql", "count": 8}, {"category": "redis", "count": 5}]
check("科目列表和题目数量正确", status == 200 and data == expected)

status, data = get("/api/questions/24")
check("题目详情仍然正常", status == 200 and isinstance(data, dict) and data.get("id") == 24)

print(f"\\n通过 {passed} / 10")`,explain:[{at:'import json',to:'import urllib.request',text:'urllib.parse.urlencode 把参数字典编码成 a=1&b=2 的格式。'},{at:'BASE = sys.argv[1]',to:'passed = 0',text:'服务地址和通过数。'},{at:'def check(name, ok):',to:'passed += bool(ok)',text:'检查一项并打印结果。'},{at:'def get(path, **params):',to:'path += "?" + urllib.parse.urlencode(params)',text:'**params 收集所有“名字=值”形式的参数，比如 get(路径, page=3)，自动拼成查询字符串。'},{at:'try:',to:'return status, None',text:'发请求，返回状态码和解析好的 JSON，和前几关一样。'},{at:'def ids(data):',to:'return [q["id"] for q in data["items"]]',text:'取出一页结果里所有题目的编号；格式不对时返回 None。'},{at:'status, data = get("/api/health")',to:'check("健康检查仍然正常"',text:'健康检查。'},{at:'status, data = get("/api/questions")',to:'and data.get("page") == 1 and data.get("size") == 10)',text:'不带参数：第 1 页，10 道，总数 24，page 和 size 也要返回。'},{at:'_, data = get("/api/questions", page=3)',to:'check("第 3 页只剩 4 道（21–24 号）"',text:'第 3 页跳过 20 道，剩下 4 道，并且按编号排好序。'},{at:'seen = []',to:'check("翻页不重复、不遗漏", seen == list(range(1, 25)))',text:'每页 7 道，取 4 页（7 × 4 = 28 > 24），拼起来要正好是 1 到 24，顺序一致，不多不少。'},{at:'_, data = get("/api/questions", category="go", page=3, size=5)',to:'check("科目和分页可以一起用"',text:'go 有 11 道，每页 5 道，第 3 页只剩最后 1 道，就是 12 号。总数也是筛选后的数量。'},{at:'_, data = get("/api/questions", q="索引")',to:'check("按关键词搜索"',text:'题目里包含“索引”的只有 2 号和 15 号。'},{at:'_, data = get("/api/questions", q="\' OR',to:'check("搜索词里的 SQL 注入不起作用"',text:'关键词同样要用占位符，注入的字符串只是一个普通的搜索词，什么也搜不到。'},{at:'bad = [',to:'check("不合法的 page 和 size 返回 400"',text:'四种不合法的参数：0、不是数字、超过 50、负数，都要返回 400。'},{at:'status, data = get("/api/categories")',to:'check("科目列表和题目数量正确"',text:'科目按名字排序，数量和种子数据一致。'},{at:'status, data = get("/api/questions/24")',to:'check("题目详情仍然正常"',text:'详情接口不受影响。'},{at:'print(f"\\n通过 {passed} / 10")',text:'打印总的通过数。'}]},
  {title:'这一关学到了什么',body:'一、分页用 LIMIT 和 OFFSET，一定要配合 ORDER BY；总数用 COUNT(*) 单独查，条件和列表相同；\n二、搜索用 LIKE \'%词%\'，搜索词同样走占位符；\n三、GROUP BY 分组统计，让页面上的科目由数据决定，而不是写死在代码里；\n四、来自用户的参数都要检查：有默认值、有范围、错了返回 400 和清楚的提示；\n五、改接口的返回格式会影响所有调用方，要一起改。下一关就按这份新约定，把题库页面做完整：搜索框、翻页、题目详情页。'}
 ],quiz:[
 {id:'pj-query-1',q:'每页 10 条，要取第 3 页，SQL 应该怎么写？',options:['LIMIT 10 OFFSET 20','LIMIT 3 OFFSET 10','LIMIT 30 OFFSET 0','LIMIT 10 OFFSET 30'],why:['','LIMIT 是每页条数，OFFSET 是跳过的条数，这里写反了。','这样会取出前 30 条，而不是第 3 页的 10 条。','跳过 30 条得到的是第 4 页。'],answer:0,explain:'OFFSET = (页码 - 1) × 每页条数 = (3 - 1) × 10 = 20，再取 10 条，就是第 21 到 30 条。'},
 {id:'pj-query-2',type:'judge',q:'分页查询不写 ORDER BY 也没关系，数据库每次都会按插入顺序返回。',answer:false,explain:'错误。没有 ORDER BY 时，数据库不保证返回顺序，翻页时可能有的数据重复出现、有的永远看不到。分页一定要按一个确定的顺序排序，比如按 id。'},
 {id:'pj-query-3',q:'列表接口为什么要另外返回 total（符合条件的总数）？',options:['前端要用它算出一共有几页、显示“共 N 道题”','total 可以让数据库查询变得更快','少了 total 字段，JSON 就不能被解析','total 用来告诉前端这一页有几条数据'],why:['','多查一次 COUNT 反而多一点开销。','JSON 的格式和有没有 total 无关。','这一页有几条，看 items 的长度就知道。'],answer:0,explain:'items 只是当前这一页，前端要知道总数才能算出页数、决定“下一页”按钮能不能点。'},
 {id:'pj-query-4',q:'SQL 里 title LIKE \'%索引%\' 的意思是？',options:['title 里任何位置包含“索引”','title 正好等于“索引”两个字','title 以“索引”开头','title 以“索引”结尾'],why:['','正好等于要用 = 比较。','以它开头的写法是 LIKE \'索引%\'。','以它结尾的写法是 LIKE \'%索引\'。'],answer:0,explain:'% 代表任意多个字符（包括零个），两边都有 %，就是“任意位置包含”。'},
 {id:'pj-query-5',type:'multi',q:'下面哪些请求参数应该返回 400？（多选）',options:['page=0','size=20（上限是 50）','page=abc','page=100（超出了总页数）'],why:['','20 在 1 到 50 之间，是合法的每页条数。','','页码超出范围不算错误，返回空的 items 就行。'],answers:[0,2],explain:'参数格式不对或超出允许范围，是调用方的问题，返回 400 并说明规则。页码太大只是“这一页没有数据”，返回 200 和空列表。'},
 {id:'pj-query-6',q:'为什么要限制 size 的最大值？',options:['防止一个请求拖出整张表，压垮服务器','数据库规定一次最多返回 50 行数据','size 太大时返回的 JSON 格式会出错','前端页面一次最多显示 50 条数据'],why:['','数据库没有这样的规定。','数据多少和 JSON 格式无关。','前端能显示多少由前端决定，这不是限制的原因。'],answer:0,explain:'size 由调用方随便填，如果不限制，有人反复请求 size=1000000，数据库和网络都会被拖慢，其他用户也受影响。'},
 {id:'pj-query-7',type:'fill',q:'SQL 里把 category 相同的行归成一组，再用 COUNT(*) 统计每组数量，用到的子句是 ＿＿。',accepted:['GROUP BY','group by'],explain:'GROUP BY category 按科目分组，配合 COUNT(*) 得到每个科目的题目数量。'},
 {id:'pj-query-8',type:'judge',q:'改了接口的返回格式（比如从数组变成对象），所有调用这个接口的页面都要跟着改。',answer:true,explain:'正确。接口是前后端之间的约定，改约定就要通知并修改所有调用方。真实项目中常用版本号（比如 /api/v2/…）让新旧格式共存一段时间。'},
 {id:'pj-query-9',type:'short',q:'说说 WHERE (? = \'\' OR category = ?) 这种写法是怎么做到“传了科目就筛选，不传就返回全部”的？',reference:'两个问号都传入科目参数。参数为空字符串时，前半部分 \'\' = \'\' 成立，整个括号为真，相当于没有这个条件；参数不为空时前半部分不成立，只有 category 等于参数的行满足条件。这样一条固定的 SQL 就能处理两种情况，参数仍然通过占位符传入。',points:['参数为空时前半部分成立，条件失效','参数不为空时按 category 筛选','同一条 SQL 处理两种情况，仍然是参数化查询'],explain:'这个技巧避免了根据参数拼接不同的 SQL，既简单又安全。'},
 {id:'pj-query-go-1',stack:'go',q:'Go 中 s.db.Query(sql, append(args, size, offset)...) 末尾的 ... 是什么意思？',options:['把切片展开成多个参数依次传入','表示后面还可以继续写参数','把多个参数合并成一个切片','表示这个参数可以不传'],why:['','Go 没有这种写法。','这是函数定义里 ...T 的作用，调用时的 ... 是展开。','Go 没有可选参数。'],answer:0,explain:'Query 的定义是 Query(query string, args ...any)，可以接收任意多个参数。调用时在切片后面写 ...，就把切片里的每个元素当作一个参数传进去。'},
 {id:'pj-query-java-1',stack:'java',q:'Spring 中 @RequestParam(defaultValue = "1") int page 收到 page=abc 时会怎样？',options:['类型转换失败，抛出异常','page 自动变成默认值 1','page 被当作 0 继续执行','请求被直接忽略不处理'],why:['','默认值只在没传参数时使用。','不会自动变成 0。','请求不会被忽略，会抛出异常。'],answer:0,explain:'字符串转整数失败会抛出类型不匹配的异常。如果不处理，会被当作程序出错返回 500，所以在 GlobalErrors 里把它统一成 400。'},
 {id:'pj-query-node-1',stack:'node',q:'函数参数写成 function f({ page = 1, size = 10 } = {}) ，调用 f({ page: 3 }) 时 size 是多少？',options:['10','undefined','3','会报错'],why:['','没传的属性使用解构时写的默认值。','page 是 3，size 没传。','有默认值，不会报错。'],answer:0,explain:'这是“解构参数 + 默认值”：传入对象里有的属性用传入的值，没有的用等号后面的默认值；末尾的 = {} 让完全不传参数时也能正常工作。'},
 {id:'pj-query-python-1',stack:'python',q:'FastAPI 中 size: int = Query(10, ge=1, le=50)，请求 size=100 时默认会怎样？',options:['返回 422 和校验错误说明','size 自动变成 50','size 自动变成默认值 10','照常执行，查出 100 条'],why:['','FastAPI 不会自动修正数值。','默认值只在没传时使用。','超出范围的值会被拒绝，不会执行函数。'],answer:0,explain:'FastAPI 自动校验参数，不合法时默认返回 422。我们用 exception_handler 处理 RequestValidationError，把它统一成 400 和 {"error": …}。'},
]};
